#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-maker. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/HealCircle/Plan.md  ·  heal magic circle ~2 m under the character, one shot ~1.5 s, green, stylized soft.
    // Rune textures are drawn by Docs/VFX/HealCircle/heal_circle_textures.py (no library shapes).
    public static class HealCircleBuild
    {
        const string Effect = "HealCircle";
        const string Root = "Assets/VFX/" + Effect;
        const string Tex = Root + "/Textures/T_HealCircle_";

        static readonly Color Core = Hex("#F4FFE0"), Mid = Hex("#7CF29A"), Outer = Hex("#1FA85A");

        [MenuItem("VFX/" + Effect + "/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");

            // 1. Textures (black background -> alpha from brightness)
            var tGlow = ImportTexture(Tex + "Glow.png", 256, alphaFromGray: true);
            var tOuter = ImportTexture(Tex + "RuneOuter.png", 512, alphaFromGray: true);
            var tInner = ImportTexture(Tex + "RuneInner.png", 512, alphaFromGray: true);
            var tBeam = ImportTexture(Tex + "Beam.png", 256, alphaFromGray: true);
            var tMote = ImportTexture(Tex + "Mote.png", 128, alphaFromGray: true);
            var tSpark = ImportTexture(Tex + "Sparkle.png", 128, alphaFromGray: true);

            // 2. Materials (all additive: dark background assumed)
            string M(string layer) => Root + "/Materials/M_HealCircle_" + layer + "_Add.mat";
            var mGlow = Material(M("Glow"), VfxBlend.Additive, tGlow);
            var mOuter = Material(M("RuneOuter"), VfxBlend.Additive, tOuter);
            var mInner = Material(M("RuneInner"), VfxBlend.Additive, tInner);
            var mBeam = Material(M("Beam"), VfxBlend.Additive, tBeam);
            var mMote = Material(M("Mote"), VfxBlend.Additive, tMote);
            var mSpark = Material(M("Sparkle"), VfxBlend.Additive, tSpark);

            var root = new GameObject("VFX_" + Effect);

            // 3a. GroundGlow: soft pool of light under the feet
            var glow = Particle(root.transform, "GroundGlow", mGlow, lifetime: 1.5f, size: 2.4f, color: Outer);
            Flat(glow, 0.01f);
            AlphaOverLifetime(glow, 0f, 0f, 0.15f, 0.6f, 0.7f, 0.5f, 1f, 0f);
            Burst(glow, 1);
            Sorting(glow, -5);

            // 3b. RuneOuter: opens fast, turns slowly clockwise, fades at the end
            var outer = Particle(root.transform, "RuneOuter", mOuter, lifetime: 1.5f, size: 2.0f, color: Color.white);
            Flat(outer, 0.02f);
            SizeOverLifetime(outer, 0f, 0.6f, 0.13f, 1f, 1f, 1.03f);
            ColorOverLifetime(outer, new[] { Core, Mid, Mid }, 0f, 0f, 0.08f, 1f, 0.73f, 1f, 1f, 0f);
            Spin(outer, 25f);
            Burst(outer, 1);
            Sorting(outer, -4);

            // 3c. RuneInner: a beat later, turns the other way, shrinks a little as it fades
            var inner = Particle(root.transform, "RuneInner", mInner, lifetime: 1.4f, size: 1.3f, color: Color.white);
            Flat(inner, 0.03f);
            Burst(inner, 1, 0.08f);
            SizeOverLifetime(inner, 0f, 0.4f, 0.15f, 1f, 0.75f, 1f, 1f, 0.7f);
            ColorOverLifetime(inner, new[] { Core, Mid }, 0f, 0f, 0.1f, 1f, 0.7f, 1f, 1f, 0f);
            Spin(inner, -45f);
            Sorting(inner, -3);

            // 3d. Beam: soft light column rising from the circle (Stretched Billboard; texture flight edge = LEFT = up)
            var beam = Particle(root.transform, "Beam", mBeam, lifetime: 1.0f, size: 1.5f, color: Core);
            Burst(beam, 1, 0.1f);
            var bm = beam.main; bm.startSpeed = 0.01f; bm.duration = 1.1f;
            Upward(beam);
            SizeOverLifetime(beam, 0f, 0.6f, 0.3f, 1f, 1f, 0.8f);
            ColorOverLifetime(beam, new[] { Core, Mid }, 0f, 0f, 0.2f, 1f, 0.6f, 0.8f, 1f, 0f);
            var br = Rend(beam);
            br.renderMode = ParticleSystemRenderMode.Stretch;
            br.velocityScale = 0f;
            br.lengthScale = 1.5f;                 // ~2.2 m tall for a 1.5 m wide quad (v2: wider, brighter)
            br.pivot = new Vector3(0f, 1f, 0f);    // bright base stays on the ground
            Sorting(beam, 0);

            // 3e. Motes: small lights rising from the rim of the circle
            var motes = Particle(root.transform, "Motes", mMote, lifetime: 1f, size: 0.08f, color: Color.white);
            var mm = motes.main;
            mm.duration = 1.5f;
            mm.startLifetime = new ParticleSystem.MinMaxCurve(0.8f, 1.2f);
            mm.startSize = new ParticleSystem.MinMaxCurve(0.05f, 0.11f);
            var me = motes.emission; me.SetBursts(new[] { new ParticleSystem.Burst(0.1f, 2, 10, 0.1f) });
            mm.maxParticles = 25;
            var ms = motes.shape; ms.enabled = true;
            ms.shapeType = ParticleSystemShapeType.Circle; ms.radius = 0.9f; ms.radiusThickness = 0.15f;
            ms.rotation = new Vector3(90f, 0f, 0f);   // circle lies on the ground (XZ)
            Rise(motes, 0.6f, 1.4f);
            var mn = motes.noise; mn.enabled = true; mn.strength = 0.2f; mn.frequency = 0.8f; mn.quality = ParticleSystemNoiseQuality.Low;
            SizeOverLifetime(motes, 0f, 1f, 1f, 0f);
            ColorOverLifetime(motes, new[] { Core, Mid }, 0f, 0f, 0.15f, 1f, 1f, 0f);
            Sorting(motes, 2);

            // 3f. Sparkles: a few twinkles inside the column, swell then shrink, quarter turn
            var spark = Particle(root.transform, "Sparkles", mSpark, lifetime: 0.5f, size: 0.2f, color: Core);
            var sm = spark.main;
            sm.duration = 1.0f;
            sm.startLifetime = new ParticleSystem.MinMaxCurve(0.4f, 0.6f);
            sm.startSize = new ParticleSystem.MinMaxCurve(0.15f, 0.25f);
            var se = spark.emission; se.SetBursts(new[] { new ParticleSystem.Burst(0.2f, 1, 6, 0.12f) });
            sm.maxParticles = 8;
            var ss = spark.shape; ss.enabled = true;
            ss.shapeType = ParticleSystemShapeType.Box; ss.scale = new Vector3(1.4f, 1.2f, 1.4f); ss.position = new Vector3(0f, 0.8f, 0f);
            Rise(spark, 0.2f, 0.4f);
            var sr = spark.rotationOverLifetime; sr.enabled = true; sr.z = new ParticleSystem.MinMaxCurve(Mathf.PI / 2f / 0.5f);
            SizeOverLifetime(spark, 0f, 0f, 0.5f, 1f, 1f, 0f);
            Sorting(spark, 3);

            // 4. Save, validate, preview (game camera 3/4, 40° down), demo scene
            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + Effect + ".prefab");
            var target = new Vector3(0f, 0.5f, 0f);
            const float d = 3.8f, a = 40f * Mathf.Deg2Rad;
            var cam = target + new Vector3(0f, Mathf.Sin(a) * d, -Mathf.Cos(a) * d);
            Finish(prefab, Root, Effect, new[] { 0.05f, 0.15f, 0.3f, 0.5f, 0.75f, 1f, 1.25f, 1.45f }, cam, target);
        }

        public static void BuildBatch() => RunBatch(Build);

        // ---------------------------------------------------------------- local helpers

        static ParticleSystemRenderer Rend(ParticleSystem ps) => ps.GetComponent<ParticleSystemRenderer>();

        static void Sorting(ParticleSystem ps, int order)
        {
            var r = Rend(ps);
            r.sortingOrder = order;
            r.maxParticleSize = 3f;
        }

        /// <summary>Flat on the ground without Horizontal Billboard: Billboard + Render Alignment Local, object rotated X 90.</summary>
        static void Flat(ParticleSystem ps, float y)
        {
            ps.transform.localPosition = new Vector3(0f, y, 0f);
            ps.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            Rend(ps).alignment = ParticleSystemRenderSpace.Local;
        }

        /// <summary>Constant turn in degrees per second (in the particle's own plane).</summary>
        static void Spin(ParticleSystem ps, float degPerSec)
        {
            var rot = ps.rotationOverLifetime;
            rot.enabled = true;
            rot.z = new ParticleSystem.MinMaxCurve(degPerSec * Mathf.Deg2Rad);
        }

        /// <summary>Emit straight up (+Y): cone with angle 0 tilted from +Z to +Y.</summary>
        static void Upward(ParticleSystem ps)
        {
            var s = ps.shape;
            s.enabled = true;
            s.shapeType = ParticleSystemShapeType.Cone;
            s.angle = 0f; s.radius = 0.001f;
            s.rotation = new Vector3(-90f, 0f, 0f);
        }

        /// <summary>Rise in world-up speed range (m/s); shape gives only the start position.</summary>
        static void Rise(ParticleSystem ps, float min, float max)
        {
            var m = ps.main; m.startSpeed = 0f;
            var v = ps.velocityOverLifetime;
            v.enabled = true;
            v.space = ParticleSystemSimulationSpace.Local;
            v.x = new ParticleSystem.MinMaxCurve(0f, 0f);
            v.y = new ParticleSystem.MinMaxCurve(min, max);
            v.z = new ParticleSystem.MinMaxCurve(0f, 0f);
        }

        static Color Hex(string h) => ColorUtility.TryParseHtmlString(h, out var c) ? c : Color.magenta;
    }
}
#endif
